_DATE_FORMATS_UNCONFIRMED = []


def transform_row(row, rt_ctx):
    """Map one cleaned input row -> output row. Raise rt.RowError to reject the row.

    `row` values arrive already text-cleaned and null-resolved per policy
    (ENC-03/04/05, NUL-01/02/03 applied and counted by the runtime).
    """
    out = {}

    # shipment_id <- ship_id  [TYP-11: VARCHAR(12); NUL-04: NOT NULL enforced by target.
    #   NUL-01 (unconfirmed): empty ship_id already resolved to None by the runtime,
    #   so an empty key quarantines here rather than loading as a blank id.]
    out["shipment_id"] = rt.not_null(
        rt.check_length(row["ship_id"], "ship_id", max_length=12), "ship_id")

    # ship_date <- date  [TYP-03 (unconfirmed): MDY vs DMY unresolved -> quarantine
    #   every value until a human confirms the format. See _DATE_FORMATS_UNCONFIRMED.]
    out["ship_date"] = rt.to_date(row["date"], "date", formats=_DATE_FORMATS_UNCONFIRMED)

    # weight_kg <- wt
