    # carrier <- carrier  [TYP-10 (unconfirmed): raw case PRESERVED (no canonicalization).
    #   TYP-11: VARCHAR(20).]
    out["carrier"] = rt.check_length(row["carrier"], "carrier", max_length=20)

    # delivered <- status  [TYP-06 (unconfirmed): Y->true, N->false; out-of-vocabulary
    #   values are row-errors. report=rt_ctx counts any case-insensitive acceptances (TYP-10).]
    out["delivered"] = rt.to_bool(row["status"], "status",
                                  mapping={"Y": True, "N": False}, report=rt_ctx)
    return out


